window.ScripturaLexicons.BDAG_PART_0294 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-01\" data-source=\"BDAG\" data-search=\"πονηρεύομαι verbo agir perversamente, pecar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πονηρεύομαι</td><td>verbo</td><td>agir perversamente, pecar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-02\" data-source=\"BDAG\" data-search=\"πονηρία, ας, ἡ substantivo feminino perversidade, maldade, malícia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πονηρία, ας, ἡ</td><td>substantivo feminino</td><td>perversidade, maldade, malícia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-03\" data-source=\"BDAG\" data-search=\"πονηρός, ά, όν adjetivo mau, perverso, maligno, de má qualidade, doente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πονηρός, ά, όν</td><td>adjetivo</td><td>mau, perverso, maligno, de má qualidade, doente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-04\" data-source=\"BDAG\" data-search=\"πονηρόφρων, ον, adjetivo de mente perversa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πονηρόφρων, ον,</td><td>adjetivo</td><td>de mente perversa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-05\" data-source=\"BDAG\" data-search=\"πονηρῶς advérbio vilmente, perversamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πονηρῶς</td><td>advérbio</td><td>vilmente, perversamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-06\" data-source=\"BDAG\" data-search=\"πόνος, ου, ὁ substantivo masculino labor, fadiga, dor, aflição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόνος, ου, ὁ</td><td>substantivo masculino</td><td>labor, fadiga, dor, aflição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-07\" data-source=\"BDAG\" data-search=\"Ποντικός, ή, όν adjetivo do Ponto, pôntico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ποντικός, ή, όν</td><td>adjetivo</td><td>do Ponto, pôntico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-08\" data-source=\"BDAG\" data-search=\"Πόντιος, ου, ὁ nome próprio masculino Pôncio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πόντιος, ου, ὁ</td><td>nome próprio masculino</td><td>Pôncio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-09\" data-source=\"BDAG\" data-search=\"πόντος, ου, ὁ substantivo masculino mar, alto-mar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόντος, ου, ὁ</td><td>substantivo masculino</td><td>mar, alto-mar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-10\" data-source=\"BDAG\" data-search=\"Πόντος, ου, ὁ nome próprio masculino Ponto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πόντος, ου, ὁ</td><td>nome próprio masculino</td><td>Ponto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-11\" data-source=\"BDAG\" data-search=\"Πόπλιος, ου, ὁ nome próprio masculino Públio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πόπλιος, ου, ὁ</td><td>nome próprio masculino</td><td>Públio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-12\" data-source=\"BDAG\" data-search=\"πορεία, ας, ἡ substantivo feminino viagem, jornada, modo de vida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορεία, ας, ἡ</td><td>substantivo feminino</td><td>viagem, jornada, modo de vida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-13\" data-source=\"BDAG\" data-search=\"πορεύω verbo ir, viajar, proceder, viver, morrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορεύω</td><td>verbo</td><td>ir, viajar, proceder, viver, morrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-14\" data-source=\"BDAG\" data-search=\"πορθέω verbo saquear, devastar, destruir, aniquilar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορθέω</td><td>verbo</td><td>saquear, devastar, destruir, aniquilar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-15\" data-source=\"BDAG\" data-search=\"πορία remissão ver πορεία BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορία</td><td>remissão</td><td>ver πορεία</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-16\" data-source=\"BDAG\" data-search=\"πορίζω verbo obter, providenciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορίζω</td><td>verbo</td><td>obter, providenciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-17\" data-source=\"BDAG\" data-search=\"πορισμός, οῦ, ὁ substantivo masculino meio de ganho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>meio de ganho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-18\" data-source=\"BDAG\" data-search=\"Πόρκιος, ου, ὁ nome próprio masculino Pórcio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πόρκιος, ου, ὁ</td><td>nome próprio masculino</td><td>Pórcio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-19\" data-source=\"BDAG\" data-search=\"πορνεία, ας, ἡ substantivo feminino prostituição, imoralidade sexual, fornicação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορνεία, ας, ἡ</td><td>substantivo feminino</td><td>prostituição, imoralidade sexual, fornicação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0294-20\" data-source=\"BDAG\" data-search=\"πορνεύω verbo fornicar, prostituir-se, praticar imoralidade sexual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πορνεύω</td><td>verbo</td><td>fornicar, prostituir-se, praticar imoralidade sexual</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0294-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πονηρεύομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πονηρεύομαι</span> depoente méd.; fut. <span class=\"greek\">πονηρεύσομαι</span>; aor. <span class=\"greek\">ἐπονηρευσάμην</span> LXX; perf. inf. <span class=\"greek\">πεπονηρεῦσθαι</span> Ex 22:7, 10 (<span class=\"greek\">πονηρός</span>; Heraclit. et al.; Demosth. 19, 32; Menand., Epitr. 133; Plut., Pomp. 640 [39, 5], Cic. 7, 4, Cato Maj. 9, 10; Ael. Aristid. 39 p. 745 D.; LXX; Test12Patr; JosAs; Philo, Spec. Leg. 2, 11; 4, 76; Jos., Ant. 15, 348; Just.), geralmente ‘ser perverso, agir perversamente’, com a implicação de contrariar os interesses de uma sociedade bem ordenada (v. <span class=\"greek\">πόνηρος</span>, início), ter disposição perversa ou agir de maneira perversa, proceder mal, cometer pecado Hm 10, 3, 2ab. Oposto a <span class=\"greek\">ἀγαθοποιεῖν</span> Hs 9, 18, 1f. <span class=\"greek\">π</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> agir perversamente para com alguém, causar dano a alguém m 4, 3, 4; 9:9; Hs 9, 22, 4. <span class=\"greek\">π</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (cometer) pecado com algo (Mi 3:4): com a língua Hv 2, 2, 3. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πονηρεύσῃ</span> não deves praticar mal algum Hs 5, 1, 5. <span class=\"greek\">οἱ</span> <span class=\"greek\">πονηρευόμενοι</span> <span class=\"greek\">ποικίλαις</span> <span class=\"greek\">πονηρίαις</span> praticantes de diversas espécies de perversidade = pecadores de toda espécie 9, 18, 3.—O part. substantivado no pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">πονηρευόμενοι</span> os malfeitores, os pecadores (OGI 515, 58; LXX; Philo, Virt. 227) B 5:13; B 6:6 (cf. para ambos Ps 21:17).—DELG s.v. <span class=\"greek\">πένομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πονηρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πονηρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πονηρός</span>; Soph., Hippocr. et al.), em nossa literatura somente no sentido ético: estado ou condição de falta de valores morais ou sociais, perversidade, vileza, malícia, pecaminosidade (Soph.; Lysias 22, 16 et al.; OGI 519, 10; PLips 119 recto e verso I, 7; LXX; En 10:16; OdeSol 11:20; Test12Patr; Philo, De Jos. 212; Jos., Ant. 10, 37; 13, 120; Just., Tat.; Mel., P. 50, 369 Bo.; Orig., Did., empréstimo no vocabulário rabínico) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:18</a>; Hv 3, 5, 4; 3, 6, 1. Com <span class=\"greek\">ἁρπαγή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:39</a>; com <span class=\"greek\">ἄνοια</span> 2 Cl 13:1; com <span class=\"greek\">δολιότης</span> Hs 8, 6, 2; com <span class=\"greek\">κακία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:8</a>. Na oração do Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:13</a> v.l. Em um catálogo de vícios (v. Philo, Ebr. 223) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:29</a>; 1 Cl 35:5. Cf. Hs 9, 15, 3, onde <span class=\"greek\">πονηρία</span> e outros vícios são personificados. <span class=\"greek\">πονηρία</span> <span class=\"greek\">μεγάλη</span> Hv 2, 2, 2a. Acerca de crianças <span class=\"greek\">μὴ</span> <span class=\"greek\">γινώσκοντα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πονηρίαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπολλύουσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ζωήν</span> <span class=\"greek\">ἀνθρώπων</span> que nada conhecem da perversidade que arruína a vida das pessoas Hm 2:1 (v. <span class=\"greek\">παιδίον</span> 2).—No gen. objetivo <span class=\"greek\">κόλασις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. punição pela perversidade Hs 9, 18, 1; <span class=\"greek\">ὁ</span> <span class=\"greek\">μισθὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. B 4:12. No gen. de qualidade (a traduzir como adj.; grego de boa norma [cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">τᾶς</span> <span class=\"greek\">ἡσυχίας</span> <span class=\"greek\">βίοτος</span> Eur., Bacch. 389], mas fortemente influenciado em nossa literatura pela tradição semítica, v. Leutzsch, Hermas 383 n. 44; cf. Schwyzer II 122): <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιθυμία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. desejo mau Hv 1, 1, 8; m 11:2; <span class=\"greek\">συμφυρμοὶ</span> <span class=\"greek\">πονηρίας</span> v 2, 2, 2b; <span class=\"greek\">διδάσκαλοι</span> <span class=\"greek\">πονηρίας</span> mestres maus ou gen. obj., mestres de perversidade Hs 9, 19, 2; <span class=\"greek\">τὰ</span> <span class=\"greek\">πνευματικὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. (Iren. 1, 5, 4 [Harv. I 47, 2]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a> (v. <span class=\"greek\">πνευματικός</span> 3); <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρίας</span> (oposto a <span class=\"greek\">ἄγγ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span>) Hm 6, 2, 1; 4f; 7; 9f (cf. 1QS 3:18f). <span class=\"greek\">πλείονα</span> <span class=\"greek\">πονηρίαν</span> <span class=\"greek\">ποιεῖν</span> agir mais perversamente Hs 9, 18, 2.—Pl., acerca das diversas espécies de disposição má e de suas manifestações individuais (Demosth. 21, 19; Aristot. 1389a, 18; Jer 39:32; B-D-F §142; W-S. §27, 4; v. Rob. 408) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:26</a>; 1 Cl 8:4 (Is 1:16); Hv 3, 7, 2; m 8:3. <span class=\"greek\">αἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">ἐμμένουσιν</span> a perversidade permanece em seus corações Hv 3, 6, 3 (aqui o pl. poderia referir-se à pluralidade das pessoas envolvidas, pois se pretende indicar praticamente uma só espécie de perversidade). Sobre <span class=\"greek\">πονηρεύεσθαι</span> <span class=\"greek\">ποικίλαις</span> <span class=\"greek\">πονηρίαις</span> Hs 9, 18, 3, v. <span class=\"greek\">πονηρεύομαι</span>.—V. também <span class=\"greek\">ἁγιάζω</span> 4, <span class=\"greek\">ἀποβάλλω</span> 1b, <span class=\"greek\">ἀφαιρέω</span> 2a, <span class=\"greek\">κατισχύω</span> 2, <span class=\"greek\">παύω</span> 2.—DELG s.v. <span class=\"greek\">πένομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πονηρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πονηρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (v. <span class=\"greek\">πονέω</span>, <span class=\"greek\">πόνος</span>; Hes., Thu.+) comp. <span class=\"greek\">πονηρότερος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:26</a>; superl. <span class=\"greek\">πονηρότατος</span> (Diod S 14, 4, 2; PRyl III, 493, 89) Hm 3:5.—Frequentemente na literatura grega o oposto de <span class=\"greek\">ἀγαθός</span>/<span class=\"greek\">καλός</span> ou <span class=\"greek\">χρηστός</span>.</p><p class=\"entry-text\">① Relativo a não ter valor moral ou social, perverso, maligno, mau, vil, imprestável, vicioso, degenerado</p><p class=\"entry-text\">ⓐ Como adj.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Acerca de seres humanos ou transcendentes (desde Trag. e Ps.-X., Rep. Ath. 1, 1; Is 9:16; Sir 25:16, 25; TestJob 43:5; ApcMos 21 <span class=\"greek\">γύναι</span>; Philo, Joseph., Just.) <span class=\"greek\">ὁ</span> <span class=\"greek\">πον</span>. <span class=\"greek\">ἄνθρωπος</span> (Plut., Alcib. 196 [13, 4]; cf. GrBar 13:1, 3; Philo, Exsecr. 149; Jos., Ant. 7, 291; Just., A II, 12, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:35a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:45a</a> (onde se deve suprir <span class=\"greek\">ἄνθρωπος</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:13</a>. <span class=\"greek\">δοῦλος</span> <span class=\"greek\">πον</span>. (Comp. 120; Jos., Ant. 2, 55; 16, 296) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:32</a>; 25:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:22</a> (cf. PFouad 25 verso I, 2 [II d.C.] tratamento dirigido a um auxiliar incompetente); <span class=\"greek\">γενεὰ</span> <span class=\"greek\">πον</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:39</a>, 45b; 16:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:29</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:34</a>. <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">πον</span>. desordeiros, rufiões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:5</a>. As pessoas são chamadas <span class=\"greek\">πονηροί</span> em contraste com Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:11</a> (aqui o componente de distinção entre classes encontra expressão dramática); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:13</a> (Iambl., Vi. Pyth. 18, 82 <span class=\"greek\">ἀληθέστατον</span> … <span class=\"greek\">πονηροὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span>).—Acerca de espíritos hostis <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρόν</span> (Cat. Cod. Astr. X 180, 16; 186, 4; cf. EGoodspeed, The Harrison Papyri, n. 1, 7: ClPh 5, 1910, 321) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:15f</a>. Pl. (Cyranides p. 51, 14; Just., D. 30, 2 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:21</a>; 8:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:12f</a>. Acerca do espírito maligno que disputa com o Espírito Santo um lugar na alma humana (cf. 1 Km 16:14–23) Hm 5, 1, 2 e 3. <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">πον</span>. B 9:4 (Just., A II, 9, 4, D. 105, 3; cf. Paus. Attic. <span class=\"greek\">τ</span>, 18 e Just., A I, 66, 4 <span class=\"greek\">πονηροὶ</span> <span class=\"greek\">δαίμονες</span>; Julian p. 371, 5; 11 Hertlein <span class=\"greek\">δαίμονες</span> <span class=\"greek\">πονηροί</span>; PLips 34 recto, 8 [375 d.C.] <span class=\"greek\">π</span>. <span class=\"greek\">δαίμων</span>. Did., Gen. 45, 4 <span class=\"greek\">αἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">δυνάμεις</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">πονηρὸς</span> <span class=\"greek\">ἄρχων</span> 4:13 (<span class=\"greek\">ἄρχων</span> 1c).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Acerca de coisas <span class=\"greek\">βουλή</span> (Menand., Mon. 134 [568 Mei.]) B 6:7 (Is 3:9); 19:3; D 2:6; Hv 1, 2, 4b (<span class=\"greek\">βουλή</span> 1). <span class=\"greek\">διαλογισμοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:4</a> (<span class=\"greek\">διαλογισμός</span> 2). <span class=\"greek\">διδαχή</span> Hm 6, 2, 7 (<span class=\"greek\">παντὶ</span> <span class=\"greek\">ἔργῳ</span> é dat. de desvantagem [Schwyzer II 150f]). <span class=\"greek\">δόλος</span> (SIG 693, 6 [129 a.C.]) IEph 7:1. <span class=\"greek\">ἐπιθυμία</span> (-<span class=\"greek\">αι</span>: Dio Chrys. 4, 89) 2 Cl 16:2; Hv 1, 1, 8b; 1, 2, 4c; Hs 6, 2, 1 e frequentemente. <span class=\"greek\">ἔργον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:18</a>; Hv 1, 2, 4b. (TestAbr A 6 p. 83, 28 [Stone p. 14] com o oposto <span class=\"greek\">ἀγαθόν</span>.) <span class=\"greek\">ἔργα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:19</a>; 7:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:12b</a>; 2J 11; Hv 3, 7, 6; 3, 8, 4 e outros. <span class=\"greek\">θησαυρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:35b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:45b</a> (aqui <span class=\"greek\">θης</span>. deve ser suprido pelo contexto). <span class=\"greek\">καρδία</span> (ApcMos 13; cf. Menand., Fgm. 540, 8 [=538 Kö.], <span class=\"greek\">ψυχή</span>) 1 Cl 3:4; <span class=\"greek\">καρδία</span> <span class=\"greek\">πονηρὰ</span> <span class=\"greek\">ἀπιστίας</span> (gen. de qualidade; v. Schwyzer sob <span class=\"greek\">πονηρία</span>; B-D-F §165; definição Mlt. 74) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:12</a>. <span class=\"greek\">καταλαλιά</span> Hm 2:3. <span class=\"greek\">καύχησις</span> arrogante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:16</a>; <span class=\"greek\">λόγοι</span> <span class=\"greek\">π</span>. palavras maliciosas (Menand., Mon. 822 [542 Mei.]) 3J 10. Acerca do <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> D 5:1; cf. B 4:10 (PsSol 10:1). <span class=\"greek\">ὀφθαλμὸς</span> <span class=\"greek\">π</span>. (<span class=\"greek\">ὀφθαλμός</span> 1 e v. 3 abaixo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:22</a>. <span class=\"greek\">πρᾶγμα</span> (Menand., Epitr. 1107 S. [749 Kö.]; Fgm. 530 Kö.; TestAbr A 4 p. 81, 5 [Stone p. 10]; Tat. 17, 3) Hv 1, 1, 8a; <span class=\"greek\">ῥᾳδιούργημα</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:14</a>. <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">π</span>. palavra caluniosa, má (SIG 1175, 16; Jdth 8:8, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:11</a> v.l. (a <span class=\"greek\">ῥ</span>. é ‘má’ porque seu conteúdo consiste, como indica o contexto, em falsas acusações); Hs 5, 3, 6; <span class=\"greek\">συνείδησις</span> <span class=\"greek\">π</span>. consciência má, culpada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:22</a> (a consciência não é em si intrinsecamente má, mas as más obras a carregam de um conteúdo mau; B 19:12; D 4:14; Hm 3:4; <span class=\"greek\">ὑπόνοιαι</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:18</a> v.l. <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρότατον</span> <span class=\"greek\">ψεῦσμα</span> o mais perverso pecado da mentira Hm 3:5. Acerca do nome de um cristão <span class=\"greek\">ἐκβάλλειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πονηρόν</span> rejeitar o nome como vil (isto é, como usado somente por pessoas sem valor) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:22</a> (cf. Ath. 2, 2).—No juízo dos cristãos, uma estreita ligação com o pecado é a característica principal desta era: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐνεστῶτος</span> <span class=\"greek\">πονηροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:4</a>. Cf. <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">πονηραί</span> <span class=\"greek\">εἰσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:16</a>.—B 2:1. Sing. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:13</a>.</p><p class=\"entry-text\">ⓑ Como substantivo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Pessoa perversa ou mal-intencionada, malfeitor (Dt 21:21; Esth 7:6; Just., A I, 27, 1; Ath. 2, 3; Theoph. Ant. 2, 37 [p. 198, 22]) <span class=\"greek\">ὁ</span> <span class=\"greek\">πονηρός</span> (o art. é genérico) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:13</a> (Dt 17:7, cf. 19:19 e outros; PZaas, JBL 103, ’84, 259–61); B 19:11 v.l. (mas <span class=\"greek\">τὸ</span> <span class=\"greek\">πον</span>. no texto).—Pl. <span class=\"greek\">πονηροὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγαθοί</span> (cf. Philo, Praem. 3; Jos., Ant. 6, 307; 8, 314 Deus <span class=\"greek\">ἀγαπᾷ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγαθούς</span>, <span class=\"greek\">μισεῖ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πονηρούς</span>; Iren. 1, 24, 2 [Harv. I 198, 4]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:45</a>; 22:10. Oposto a <span class=\"greek\">οἱ</span> <span class=\"greek\">δίκαιοι</span> 13:49 (cf. T. Kellis 22, 48f). Com <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀχάριστοι</span> (v. <span class=\"greek\">ἀχάριστος</span>; também Lucian, Timon 48, talvez de uma comédia [III p. 654 Kock]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:35</a>. Com <span class=\"greek\">ἁμαρτωλοί</span> B 4:2.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πονηρός</span> o Maligno=o diabo (que não é definido como pecador, mas como aquele que é moralmente destrutivo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:13f</a>; 5:18, 19 (<span class=\"greek\">κεῖμαι</span> 3d); B 2:10; B 21:3; MPol 17:1; AcPlCor 2:2, 15) <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πονηροῦ</span> <span class=\"greek\">εἶναι</span> ser filho do Maligno (<span class=\"greek\">ἐκ</span> 3a, fim) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:12a</a>; cf. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πονηροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:38</a>, caso <span class=\"greek\">πον</span>. seja masc. aqui.—O gen. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πονηροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:37</a>; 6:13 pode também ser entendido como masc. (assim é entendido por Ps.-Clem., Hom. 3, 55 p. 51, 19; 21; Tertuliano, Cipriano, Orígenes, Crisóstomo; KFritzsche, JWeiss; v. também Schniewind sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:13</a>; Weymouth, Goodsp.;—é entendido como neut. [v. <span class=\"greek\">γ</span>] por Agostinho: WMangold, De Ev. sec. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:13</a>, 1886; BWeiss, Zahn, Wlh.; Harnack, SBBerlAk 1907, 944; PFiebig, D. Vaterunser 1927, 92; Betz, SM 380f; 405–13; Mft., NRSV marg.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:4</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:3</a>; D 8:2. Estas passagens podem também pertencer a</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρόν</span> (aquilo que é) mau, o mal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:45c</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:22</a> (semelhantemente Plut., Mor. 82c; v. também <span class=\"greek\">εἶδος</span> 2); B 19:11. <span class=\"greek\">πᾶν</span> <span class=\"greek\">πον</span>. toda espécie de mal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:11</a>; <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρὸν</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> (cf. Dt 17:2; 4 Km 21:2, 20) Hm 4, 2, 2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a> v.l.; 1 Cl 18:4 (Ps 50:6). <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρὸν</span> <span class=\"greek\">τοῦτο</span> este ato vergonhoso GJs 13:1. <span class=\"greek\">ἀγρυπνεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. D 5:2 e <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. B 20:2 v. <span class=\"greek\">ἀγρυπνέω</span> 2. <span class=\"greek\">ἐλάλησέν</span> <span class=\"greek\">τι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">πονηρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:21</a> (cf. JosAs 6:6).—Pl., pensamentos perversos, más obras (Gen 6:5; 8:21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:4</a>; 12:35c; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:20</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:18</a>; 2 Cl 8:2. <span class=\"greek\">δύο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πονηρά</span> duas coisas más B 11:2 (Jer 2:13 v.l.).—<span class=\"greek\">πονηρόν</span> <span class=\"greek\">ἐστίν</span> <span class=\"greek\">τινι</span> é mau para alguém Hm 5, 1, 4.—<span class=\"greek\">ῥύσασθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">πονηροῦ</span> D 10, 5.</p><p class=\"entry-text\">② Relativo a ser tão deficiente em qualidade no sentido físico que não tem valor, de má qualidade, imprestável (X., Pla. et al.) <span class=\"greek\">καρποί</span> (Ael. Aristid. 23, 57K.=42 p. 787 D.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:17f</a> (a mesma ideia 13:48; cf. Jer 24:8 <span class=\"greek\">τὰ</span> <span class=\"greek\">σῦκα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πονηρά</span>).</p><p class=\"entry-text\">③ Relativo a estar em condição física mórbida</p><p class=\"entry-text\">ⓐ Em referência a uma parte do corpo, doente (Pla., Prot. 313a <span class=\"greek\">σῶμα</span>; <span class=\"greek\">πονηρῶς</span> <span class=\"greek\">ἔχειν</span> ‘estar mal’, ‘estar doente’ desde Thu. 7, 83, 3), acerca do olho (cf. Pla., Hipp. Min. 374d <span class=\"greek\">πονηρία</span> <span class=\"greek\">ὀφθαλμῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:34</a> (Weizsäcker, BWeiss, HHoltzmann, Fitzmyer, Goodsp., NRSV. Mas v. s.v. <span class=\"greek\">ἁπλοῦς</span>, <span class=\"greek\">λύχνος</span> b, <span class=\"greek\">ὀφθαλμός</span> 1, também 1a<span class=\"greek\">β</span> acima e os quatro artigos ET 53, ’42, 181f; 354f; 54, ’42, 26; 26f).</p><p class=\"entry-text\">ⓑ Em referência ao estado de alguma enfermidade, doloroso, virulento, grave (desde Theognis 274) <span class=\"greek\">ἕλκος</span> ferida, úlcera (Dt 28:35; Job 2:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:2</a>.—V. Lofthouse s.v. <span class=\"greek\">κακός</span>, fim; WBrandt, ZNW 14, 1913, 189ff.—DELG s.v. <span class=\"greek\">πένομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πονηρόφρων, ον,</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πονηρόφρων</span>, <span class=\"greek\">ον</span>, (<span class=\"greek\">πονηρός</span>, <span class=\"greek\">φρήν</span>) gen. <span class=\"greek\">ονος</span>, relativo a ter a mente orientada de maneira moral ou socialmente destrutiva, de mente perversa, com <span class=\"greek\">αὐθάδης</span> D 3:6 (a palavra encontra-se somente aqui e em Apost. Constit. 7, 7, que depende desta passagem).—DELG s.v. <span class=\"greek\">φρήν</span> II.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πονηρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πονηρῶς</span> adv. de <span class=\"greek\">πονηρός</span> (Thu., Aristoph. et al.), vilmente, perversamente, com <span class=\"greek\">ἀφρόνως</span> Hv 5:4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πένομαι</span> ‘labutar’; Hom.+)</p><p class=\"entry-text\">① Trabalho que envolve muito esforço ou dificuldade, labor (árduo), labuta (Onesicritus [c. 310 a.C.]: 134 Fgm. 17a Jac.: por causa da <span class=\"greek\">ὕβρις</span> dos seres humanos, Zeus pôs fim à situação utópica na Índia e enviou <span class=\"greek\">πόνος</span> à vida dos seres humanos [cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">λύπαις</span> Gen 3:17]; Ps 89:10; Philo; Jos., Ant. 3, 49; 18, 244) <span class=\"greek\">πόνον</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:13</a> (<span class=\"greek\">πόνον</span> <span class=\"greek\">ἔχειν</span>: Il. 15, 416; Hes., Shield 305; Paus. 4, 16, 3. Como sinal de distinção, SJohnstone, Virtuous Toil, Vicious Work—Xenophon on Aristocratic Style: ClPh 89, ’94, 219–40.—Theocr. 7, 139 apresenta <span class=\"greek\">π</span>. com um part. no sentido de ‘esforçar-se’). <span class=\"greek\">μετὰ</span> <span class=\"greek\">πόνου</span> com dificuldade, laboriosamente, com diligência (Pla., Soph. 230a <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολλοῦ</span> <span class=\"greek\">πόνου</span>) Dg 11:8. Segundo ABoegehold (Greek, Roman, and Byzantine Studies 23, ’82, 147–56), os anos 424–421 a.C. marcam uma tendência na direção de</p><p class=\"entry-text\">② Experiência de grande dificuldade, dor, angústia, aflição (Thu. 2, 49, 3; X., Mem. 2, 2, 5; Aelian, NA 7, 30 p. 190, 9, VH 5, 6 [CPJones, ClPh 79, ’84, 43f]; SIG 708, 11; POxy 234 II, 24; 37; Is 65:14; Job 4:5; TestJob 52:1; JosAs; ApcMos 5; Just., A I, 21, 2 <span class=\"greek\">φυγῇ</span> <span class=\"greek\">πόνων</span>) com <span class=\"greek\">πένθος</span> e <span class=\"greek\">κραυγή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:4</a> (cf. Is 35:10; Pind., P. 10, 42 em uma descrição dos bem-aventurados hiperbóreos). <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πόνῳ</span> (cf. Gen 34:25; TestJob 24:6 <span class=\"greek\">ἐν</span> <span class=\"greek\">πόνοις</span>; Just., D. 125, 5) 1 Cl 16:3f (Is 53:4). <span class=\"greek\">ἀφαιρεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόνου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> (<span class=\"greek\">ἀφαιρέω</span> 2a.—<span class=\"greek\">πόνος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχῆς</span>: Maximus Tyr. 1, 4b) v. 12 (Is 53:10f). Acerca do Crucificado <span class=\"greek\">ὡς</span> <span class=\"greek\">μηδὲ</span> <span class=\"greek\">πόνον</span> <span class=\"greek\">ἔχων</span> como se não sentisse dor alguma GPt 4:10. Acerca de uma pedra de granizo <span class=\"greek\">πῶς</span> <span class=\"greek\">πόνον</span> <span class=\"greek\">παρέχει</span> quanta dor causa, quanto dói Hm 11:20. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">π</span>. com dor (Appian, Iber. 97 §423) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:10</a>; pl. (Gen 41:51; Jos., C. Ap. 2, 146; Test Jud 18:4) <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">π</span>. (Eur., Fgm. 364 Nauck2) por causa de seus sofrimentos v. 11. <span class=\"greek\">πόνους</span> <span class=\"greek\">ὑποφέρειν</span> suportar dificuldades 1 Cl 5:4.—HKuist, Biblical Review 16, ’32, 415–20 (<span class=\"greek\">πόνος</span>, <span class=\"greek\">μόχθος</span>).—B. 540. Schmidt, Syn. II 611–25 <span class=\"greek\">πονηρός</span>. DELG s.v. <span class=\"greek\">πένομαι</span>. M-M. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ποντικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ποντικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> do Ponto (v. <span class=\"greek\">Πόντος</span>; Hdt. et al.; Just., A I, 26, 5 [Marcião]), substantivado (Socrat., Ep. 30, 14), acerca de Áquila <span class=\"greek\">Π</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">γένει</span> natural do Ponto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πόντιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πόντιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Diod S 14, 116, 3; Plut.; SIG 797, 2 [37 d.C.]; OGI 656, 4), Pôncio, nome de uma gens romana, originalmente samnita, que remonta às guerras samnitas (Cic., De Off. 2, 21, 75; Livy 9, 1), o nomen (nome intermediário ou tribal [gentílico]) de Pilatos (v. <span class=\"greek\">Πιλᾶτος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:2</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13</a>; IMg 11:1; ITr 9:1; ISm 1:2; Just., A I, 13, 3 e outros. WSchulze, Zur Geschichte latein. Eigennamen: GGAbh. V/5, 1904; JOllivier, Ponce Pilate et les Pontii: RB 5, 1896, 247–54; 594–600; MStern, The Province of Judaea: CRINT I/1, 68–70; J-PLémonon, Pilate et le gouvernement de la Judée:Textes et monuments, ’81. V. Kl. Pauly IV 1048–50.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόντος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόντος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. et al.; Arrian, Anab. 6, 19, 4; 5; Ex 15:5), o mar (alto/aberto) <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πόντον</span> <span class=\"greek\">πλέων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:17</a> v.l. (acerca dos numerosos testemunhos desta leitura, v. RBorger, TRu 52, ’87, 51–53; cf. Diod S 20, 25, 2 <span class=\"greek\">οἱ</span> <span class=\"greek\">πλέοντες</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Πόντον</span>=os que navegam pelo Ponto).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πόντος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πόντος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl., Hdt. et al.; inscrições; Philo, Deus Imm. 174; Joseph.; Just., A I, 58, 1), Ponto, originalmente o nome de um mar (o Euxino, ou mar Negro), depois a designação de um império fundado pelos persas aquemênidas no nordeste da Ásia Menor, estendendo-se do mar Negro ao Cáucaso. Após a conquista de Pompeu, uma parte dele foi transformada em província romana. Segundo Appian, Mithrid. 15 §53, muitos <span class=\"greek\">Ἕλληνες</span> haviam-se estabelecido ali. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:1</a> (sobre o endereçamento, Ps.-Callisth. 2, 11, 2, uma carta circular de Alexandre [v. <span class=\"greek\">Καππαδοκία</span>]). JMarquardt, Römische Staatsverwaltung I2, 1881, 349ff; VSchultze, Altchristl. Städte u. Landschaften II/1, 1922; Pauly-W. III 507–42; Kl. Pauly IV 1050f; BHHW III 1480.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πόπλιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πόπλιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Diod S 11, 41, 1; 13, 7, 1; 14, 47, 1 e outros; Plut.; inscrições, papiros; Philo, Leg. ad Gai. 333; Jos., Ant. 14, 236), Públio, um praenomen romano (primeiro nome ou nome pessoal; v. AWalde, Latein. etymolog. Wörterbuch2 1910 s.v. poplicus; B-D-F §41, 2; cf. Mlt-H. 155). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:7f</a> menciona um <span class=\"greek\">Π</span>. como <span class=\"greek\">πρῶτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νήσου</span> na ilha de Malta. O título é atestado também em outros lugares para Malta: IG XIV, 601 [=IGR I, 512] <span class=\"greek\">Λ</span>. <span class=\"greek\">Κα</span>[<span class=\"greek\">στρί</span>]<span class=\"greek\">κιος</span> <span class=\"greek\">Κυρ</span>(<span class=\"greek\">είνᾳ</span>) <span class=\"greek\">Προύδηνς</span> <span class=\"greek\">ἱππεὺς</span> <span class=\"greek\">Ῥωμ</span>(<span class=\"greek\">αίων</span>), <span class=\"greek\">πρῶτος</span> <span class=\"greek\">Μελιταίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάτρων</span>, <span class=\"greek\">ἄρξας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀμφιπολεύσας</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">Αὐγούστῳ</span>; CIL X, 7495 [munic]ipi Mel(itensium) primus omnium (mas v. Bruce, Acts 532f acerca desta inscrição). Em geral, dá-se por certo que era uma designação da mais alta autoridade romana na ilha (Holtzmann, Wendt, Bruce et al.). Também se pensou que se referisse a algum cargo de origem não romana (AMayr, Die Insel Malta im Altertum 1909, 116; AWikenhauser, Die AG 1921, 345f; Beginn. IV 342; v. Haenchen e outros comentários ad loc.). Diferentemente Warnecke [Romfahrt, 119–33 especialmente 123], que associa um Publius Alf(ius) Primus à ilha de Cefalênia.—BHHW III 1531. Boffo, Iscrizioni 177–81 (bibliografia). LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πόρος</span> ‘passagem, caminho’; Aeschyl., X., Pla.+), geralmente ‘ir’</p><p class=\"entry-text\">① Deslocamento planejado por uma distância considerável, viagem, jornada <span class=\"greek\">πορείαν</span> <span class=\"greek\">ποιεῖσθαι</span> (X., An. 5, 6, 11; Diod S 14, 39, 4; Cornutus 19 p. 33, 20; Plut., Mor. 162f; 2 Macc 3:8; Jos., Ant. 7, 49; 14, 128; Ar. 4:2), com indicação do destino (Jos., Ant. 14, 358 <span class=\"greek\">εἰς</span> M.) <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἱεροσόλυμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:22</a>. Muitos pensam que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:11</a> também pertence aqui: <span class=\"greek\">ὁ</span> <span class=\"greek\">πλούσιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πορείαις</span> <span class=\"greek\">αὐτοῦ</span> o rico em suas viagens (de negócios) ou, mais geralmente, em seus empreendimentos ou atividades (NRSV: ‘em meio a uma vida atarefada’). O pl. constitui forte indicação de que esta tradução é correta; mas o pl. pode ser considerado paralelo ao v. 8 <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ὁδοῖς</span> <span class=\"greek\">αὐτοῦ</span>, de modo que não podemos excluir definitivamente o sentido</p><p class=\"entry-text\">② Modo de vida, conduta (Pr 2:7.—Acerca do ‘caminho’ que se deve seguir: Socrat., Ep. 27, 5) Hs 5, 6, 6. <span class=\"greek\">κατευθύνοντες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πορείαν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁσιότητι</span> 1 Cl 48:4. A conjectura de Lightf. em 62:1 baseia-se em 48:4. Deste ponto de vista, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:11</a> seria traduzido em todos os seus caminhos (Ropes, MDibelius, et al.).—DELG s.v. <span class=\"greek\">πόρος</span> II. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορεύω</span> (Pind.+; ApcSed 15:5=p. 136, 32 Ja. <span class=\"greek\">οἱ</span> <span class=\"greek\">πορεύοντες</span>) em nossa literatura somente como méd. e pass. <span class=\"greek\">πορεύομαι</span> (Trag., Hdt.+) imperf. <span class=\"greek\">ἐπορευόμην</span>; fut. <span class=\"greek\">πορεύσομαι</span>; 1º aor. <span class=\"greek\">ἐπορεύθην</span>; perf. part. <span class=\"greek\">πεπορευομένος</span>. Sobre o aspecto futuro do pres., v. B-D-F §323, 3; Rob. 869. Sobre o sentido durativo do imperat. pres. <span class=\"greek\">πορεύου</span> em contraste com o aor. <span class=\"greek\">πορεύθητι</span>, v. B-D-F §336, 1; também Rob. 855f; 890.</p><p class=\"entry-text\">① Deslocar-se por uma área, geralmente com ponto de partida ou destino especificado, ir, prosseguir, viajar, com indicação do ponto de partida: <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> partir de alguém (cf. X., An. 4, 4, 17 ‘do acampamento de Tiribazo’) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:41</a> (imperat.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:42b</a>. <span class=\"greek\">ἐντεῦθεν</span> 13:31 (imperat.). <span class=\"greek\">ἐκεῖθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:15</a>. Com indicação do lugar para onde: <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> (X., Hell. 7, 4, 10; Is 22:15 <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>; JosAs 28:5 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὕλην</span>; ApcMos 10; Just., A II, 2, 6) para, em, para dentro de, em direção a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:20</a>; 17:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:39</a>; 4:42a; 9:56 (<span class=\"greek\">εἰς</span> <span class=\"greek\">ἑτέραν</span> <span class=\"greek\">κώμην</span>, cf. Jos., Vi. 231); 22:33 (<span class=\"greek\">εἰς</span> <span class=\"greek\">φυλακήν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:35b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:11</a>; 19:21; 20:1, 22 (<span class=\"greek\">πορεύομαι</span>=estou indo, estou prestes a ir); 22:5, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:24</a>, 25 (estou indo, estou prestes a ir); IPol 7:2; 8:2; Hv 1, 1, 3; 2, 1, 1. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκόν</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:24</a>; cf. AcPl Ha 4, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span>. Acerca de peixes <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βάθος</span> mergulhar nas profundezas B 10:10b. Também da passagem para o além, em bom sentido, acerca de Paulo e Pedro: <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">τόπον</span> 1 Cl 5:7 v.l.; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀφειλόμενον</span> (<span class=\"greek\">ὀφείλω</span> 2a<span class=\"greek\">α</span>) <span class=\"greek\">τόπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> 5:4 (assim acerca de Pedro em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:17</a>: WSmaltz, JBL 71, ’52, 211–16; v. Bruce, Acts sobre tradições variantes), e em mau sentido acerca de Judas, o delator, <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:25</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> aos gentios 18:6. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Καίσαρα</span> <span class=\"greek\">π</span>. ir a César, comparecer perante o imperador (<span class=\"greek\">ἐπί</span> 10) 25:12. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> a alguém (Soph., Ant. 892; Pla., Clit. 410c; Theophr., Char. 2, 1; Diog. L. 8, 43; Gen 26:26; TestAbr B 4 p. 109, 9 [Stone p. 66]; Just., A II, 2, 19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:9</a>; 26:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:5</a>; 15:18; 16:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:12</a>, 28; 16:28 (pres. com aspecto futuro nas três passagens de J, estou prestes a ir); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:3</a>; 1 Cl 31:4. <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:20</a>; 26:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:4b</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> atrás de algo (<span class=\"greek\">ἐπί</span> 4b<span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:4</a>; até algo (<span class=\"greek\">ἐπί</span> 4b<span class=\"greek\">γ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:26</a>; 9:11, também <span class=\"greek\">ἕως</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> 17:14. Com <span class=\"greek\">ἕως</span> e gen. de lugar 23:23 (TestAbr A 2 p. 79, 1 [Stone p. 6,1]). Com <span class=\"greek\">διά</span> e gen. de lugar, através de (X., An. 4, 7, 15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:30</a> v.l. <span class=\"greek\">ποῦ</span> (em lugar de <span class=\"greek\">ποῖ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:35a</a>. <span class=\"greek\">οὗ</span> (em lugar de <span class=\"greek\">ὅποι</span>, como 1 Macc 13:20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:28a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:6</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> seguir seu caminho, prosseguir em sua jornada 1 Cl 12:4; também <span class=\"greek\">ἐπορεύετο</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:39</a> (cf. Josh 3:4; X. An. 2, 2, 11 <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">μακροτέραν</span> [subentenda-se <span class=\"greek\">ὁδόν</span>]; Jos., Ant. 1, 282). <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> seguir pela estrada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:57</a>; também <span class=\"greek\">π</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:36</a>; AcPl Ant 13, 19f (=Aa I 237, 4).—Com finalidade indicada por inf. (Gen 37:25; JosAs 25:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:3</a>; 14:19, 31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:2</a>. Também <span class=\"greek\">ἵνα</span> 11:11.—Às vezes o lugar de onde ou para onde é facilmente suprido pelo contexto: <span class=\"greek\">θέλετε</span> <span class=\"greek\">πορεύεσθαι</span> desejais ir (isto é, à casa do incrédulo/não cristão que vos convidou) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:27</a>. <span class=\"greek\">πορ</span>. (isto é, <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἰερουσαλήμ</span>) 16:4a. <span class=\"greek\">πορ</span>. (isto é, <span class=\"greek\">εἰς</span> <span class=\"greek\">Δαμασκόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:6</a>.—O part. aor. de <span class=\"greek\">πορ</span>. é frequentemente empregado pleonasticamente para dar vivacidade à narrativa (B-D-F §419, 2.—4 Km 5:10; Josh 23:16; GrBar 15:4; Jos., Ant. 7, 318); em todo caso, a ideia de ir ou viajar não é enfatizada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:13</a>; 11:4; 18:12; 21:6; 22:15; 25:16; 27:66; 28:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:22</a>; 9:13; 13:32; 14:10 e outros.—Uso abs. (X., An. 5, 3, 2; TestAbr B 3 p. 107, 5 [Stone p. 62] <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀναστάντες</span> <span class=\"greek\">ἐπορεύοντο</span>) <span class=\"greek\">ἐπορεύθησαν</span> partiram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a>. <span class=\"greek\">πορεύθητι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πορεύεται</span> vai!, e ele vai (cf. PGM 1, 185 <span class=\"greek\">πορεύου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπελεύσεται</span>) 8:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:8</a> (oposto a <span class=\"greek\">ἔρχεσθαι</span>, como Epict. 1, 25, 10 <span class=\"greek\">Ἀγαμέμνων</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">μοι</span> ‘<span class=\"greek\">πορεύου</span> …’. <span class=\"greek\">πορεύομαι</span>. ‘<span class=\"greek\">ἔρχου</span>’. <span class=\"greek\">ἔρχομαι</span>; TestJob 34:5 <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">πορεύσομαι</span> <span class=\"greek\">ἐληλύθημεν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἵνα</span> …).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:37</a>; estar a caminho, estar viajando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:38</a>; 13:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:3</a>.—<span class=\"greek\">ἔμπροσθέν</span> <span class=\"greek\">τινος</span> (UPZ 78, 15 [159 a.C.] <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐπορευόμην</span>; Josh 3:6): <span class=\"greek\">ἔ</span>. <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">πορεύεται</span> vai à frente deles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:4</a> (escol. sobre Apollon. Rhod. 1, 577 <span class=\"greek\">προπορεύεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιμήν</span>); cf. B 11:4 (Is 45:2). <span class=\"greek\">μὴ</span> <span class=\"greek\">πορευθῆτε</span> <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">αὐτῶν</span> não vades atrás deles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a> (<span class=\"greek\">ὀπίσω</span> 2a). <span class=\"greek\">προθύμως</span> (+ <span class=\"greek\">μετὰ</span> <span class=\"greek\">σπουδῆς</span> v.l.) <span class=\"greek\">ἐπορεύετο</span> caminhava com presteza MPol 8:3.—<span class=\"greek\">πορεύου</span>=segue teu caminho (Diog. L. 4, 11): <span class=\"greek\">πορεύου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">εἰρήνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:50</a>; 8:48 ou <span class=\"greek\">ἐν</span> <span class=\"greek\">εἰρήνῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:36</a> v. <span class=\"greek\">εἰρήνη</span> 2a.—Em linguagem figurada, acerca da vida em geral (Dio Chrys. 58 [75], 1 <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βίου</span>); abs. <span class=\"greek\">πορευόμενοι</span> enquanto passam (Jülicher, Gleichn. 529) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:14</a> (outro sentido: passo a passo).—GKilpatrick, JTS 48, ’47, 61–63 (nos evangelhos sinót.).</p><p class=\"entry-text\">② Conduzir-se, viver, andar (cf. Soph., Oed. Rex 884; LXX; PsSol 18:10) seguido de <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>: (En 99:10 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁδοῖς</span> <span class=\"greek\">δικαιοσύνης</span>; TestReub 1:6; 4:1 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁπλότητι</span> <span class=\"greek\">καρδίας</span>; TestIss 3:1; TestAsh 4:5) <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">θανάτου</span> B 19:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀληθείᾳ</span> (Tob 3:5 BA; Pr 28:6) Hm 3:4. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀκακίᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἁπλότητι</span> v 2, 3, 2. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀσελγείαις</span> <span class=\"greek\">κτλ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:3</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἁγνότητι</span> <span class=\"greek\">ταύτῃ</span> Hm 4, 4, 4. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁσιότητι</span> 1 Cl 60:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐντολαῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> (cf. Ps 118:1 <span class=\"greek\">ἐν</span> <span class=\"greek\">νόμῳ</span> <span class=\"greek\">κυρίου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:6</a>; cf. Pol 2:2; 4:1; Hs 6, 1, 1–4. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">προστάγμασιν</span> 5, 1, 5.—<span class=\"greek\">κατά</span> <span class=\"greek\">τι</span> (Num 24:1; Wsd 6:4) <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐπιθυμίας</span> segundo as paixões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:3</a>; Jd 16, 18.—<span class=\"greek\">τῇ</span> <span class=\"greek\">ὀρθῇ</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">πορ</span>. seguir o caminho reto Hm 6, 1, 2 (sobre o dat., v. B-D-F §198, 5; Rob. 521 e SIG 313, 20; LXX [referências em Johannessohn, Kasus 57f]). <span class=\"greek\">ταῖς</span> <span class=\"greek\">ὁδοῖς</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:16</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Κάϊν</span> Jd 11. <span class=\"greek\">τῷ</span> <span class=\"greek\">φόβῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> viver no temor do Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:31</a>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐντολαῖς</span> <span class=\"greek\">μου</span> Hs 7, 6f. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐπιθυμίαις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span> 8, 11, 3.—<span class=\"greek\">πορ</span>. <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">τινός</span> no sentido de ‘buscar estreita relação com’ (cf. Judg 2:12; 3 Km 11:10; Sir 46:10) <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">μιασμοῦ</span> <span class=\"greek\">πορευόμενοι</span> seguem (isto é, satisfazem) sua natureza física em desejo que contamina <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a>. <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπιθυμιῶν</span> Hv 3, 7, 3.</p><p class=\"entry-text\">③ Ir para a própria morte, extensão fig. eufemística de 1 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:33</a> <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span> <span class=\"greek\">πορεύεσθαι</span>): morrer (SyrBar 14:2; Julian, Letter 14 p. 385d) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:22</a>. (Sobre a figura da morte como viagem, v. RLattimore, Themes in Gk. and Lat. Epitaphs: Illinois Studies in Language and Literature 28 nos. 1–2, §43 [=ed. 1962, 169–71]).—DELG s.v. <span class=\"greek\">πόρος</span> II. M-M s.v. <span class=\"greek\">πορεύομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορθέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορθέω</span> imperf. <span class=\"greek\">ἐπόρθουν</span>; 1º aor. <span class=\"greek\">ἐπόρθησα</span> (Hom.+; OGI 201, 17; BGU 588, 3 <span class=\"greek\">πορθοῦντες</span> <span class=\"greek\">ὑμᾶς</span>; 4 Macc 4:23; 11:4; GrBar 1:1; Jos., Bell. 4, 405, Ant. 10, 135 <span class=\"greek\">τὰ</span> <span class=\"greek\">Ἱεροσόλυμα</span>), atacar e causar destruição completa, saquear, devastar, destruir, aniquilar <span class=\"greek\">τὶ</span> algo. <span class=\"greek\">ἐπόρθουν</span> <span class=\"greek\">αὐτήν</span> (isto é, <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) eu tentava destruir a congregação de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:13</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἥν</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">ἐπόρθει</span> a fé que outrora tentava aniquilar v. 23. <span class=\"greek\">τινά</span> alguém (Aeschyl. et al.; Diod S 11, 32, 1; v. BGU acima) <span class=\"greek\">π</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐπικαλουμένους</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:21</a>.—P-HMenoud, EHaenchen Festschr. ’64, 178–86 (Ac, Gal).—DELG s.v. <span class=\"greek\">πέρθω</span>. M-M. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορία</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορία</span> v. <span class=\"greek\">πορεία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορίζω</span> (Trag., Thu.+), fazer com que algo se torne disponível, obter, providenciar <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τροφήν</span> alimento para si mesmo (Horapollo 1, 42 <span class=\"greek\">αἱ</span> <span class=\"greek\">τροφαὶ</span> <span class=\"greek\">πορίζονται</span>; PGrenf II, 14a, 11 [III a.C.] <span class=\"greek\">πόρισόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τροφήν</span>; Aelian, VH 13, 26 e Jos., Ant. 8, 13 <span class=\"greek\">π</span>. <span class=\"greek\">αὑτῷ</span> <span class=\"greek\">τι</span>) B 10:4.—DELG s.v. <span class=\"greek\">πόρος</span> II.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πορίζω</span>; Polyb. et al.; inscrições [New Docs 4, 169]; Wsd 13:19; 14:2; EpArist 111; Philo, Op. M. 128; Jos., Bell. 2, 603), meio de ganho (assim Plut., Cato Maj. 351 [25, 1] <span class=\"greek\">δυσὶ</span> <span class=\"greek\">μόνοις</span> <span class=\"greek\">πορισμοῖς</span>, <span class=\"greek\">γεωργίᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φειδοῖ</span>=ele tinha somente dois meios de ganho: agricultura e frugalidade; TestIss 4:5 v.l.; cf. o emprego de <span class=\"greek\">πορίζω</span> acerca de um mago impostor Aesop, Fab. 112a H.=56 H-H. v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:5</a>, seguido de jogo de palavras no v. 6.—DELG s.v. <span class=\"greek\">πόρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πόρκιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πόρκιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Polyb., Plut.; Jos., Ant. 20, 182), Pórcio, nome de uma gens romana à qual pertenciam, entre outros, os Catões. Festo, o procurador, pertencia a ela (v. <span class=\"greek\">Φῆστος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:27</a>.—Pauly-W. XXII 220–27; Kl. Pauly IV 1059.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορνεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορνεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (acerca de diversas espécies de ‘relações sexuais não sancionadas’: Demosth. et al.; LXX, En, Test12Patr; GrBar [em listas de vícios]; AscIs, Philo, apologistas, exceto Ar. Com <span class=\"greek\">φθορά</span> Iren. 1, 28, 1 [Harv. I 220, 14])</p><p class=\"entry-text\">① Relações sexuais ilícitas, prostituição, impudicícia, fornicação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:1ab</a> (CdeVos, NTS 44, ’98, 104–14); 6:13 (sobre 1 Cor 5–6, v. PTomson, Paul and the Jewish Law: CRINT III/1, ’90, 97–102); Hm 4, 1, 1. Em uma lista de vícios (cf. AscIs 2:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:29</a> v.l. Com <span class=\"greek\">ἀκαθαρσία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:5</a>. Distinguida de <span class=\"greek\">μοιχεία</span> (Philo, Mos. 1, 300; v. também <span class=\"greek\">πορνεύω</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:21</a> (WGabriel, Was ist ‘porneia’ im Sprachgebr. Jesu?: Ethik 7, ’31, 106–9; 363–69); Hm 8:3; D 5:1 (o pl. denota atos individuais). Por outro lado, <span class=\"greek\">μοιχεία</span> aparece como <span class=\"greek\">πορνεία</span> (cf. Sir 23:23) Hm 4, 1, 5. Acerca da infidelidade sexual de uma mulher casada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a>; 19:9 (para a opinião de que nestas passagens se faz referência a graus proibidos de casamento, v. 2 abaixo.—JSickenberger, TQ 123, ’42, 189–206, ZNW 42, ’49, 202ff; KStaab [<span class=\"greek\">παρεκτός</span> 2]; AAllgeier, Angelicum 20, ’43, 128–42. Cf. AFridrichsen, SEÅ 9, ’44, 54–58; AIsaksson, Marriage and Ministry in the New Temple, ’65, 127–42 [bibliografia]; v. também JFitzmyer, TS 37, 76, 197–226). Causada pela luxúria D 3:3. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πορνείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:2</a> (o pl. indica os diversos fatores que podem ocasionar imoralidade sexual; PTomson [v. acima] 103–8). BMalina, Does Porneia Mean ‘Fornication’? NovT 14, ’72, 10–17. <span class=\"greek\">φεύγειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. 6:18. Também <span class=\"greek\">ἀπέχεσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:3</a> (cf. Tobit 4:12). <span class=\"greek\">ἐκ</span> <span class=\"greek\">π</span>. <span class=\"greek\">γεννηθῆναι</span> ser filho ilegítimo, bastardo (cf. Cephalion [II d.C.]: 93 Fgm. 5 p. 444, 5 Jac. <span class=\"greek\">ἐγέννησε</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πορ</span>.; Gen 38:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:41</a>. Sobre <span class=\"greek\">ἀπέχεσθαι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πορνείας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνικτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:20</a> (cf. v. 29; 21:25 e v. 2 abaixo), v. a bibliografia s.v. <span class=\"greek\">πνικτός</span> e em BBacon, The Apost. Decree against <span class=\"greek\">πορνεία</span>: Exp. 8ª série, 7, 1914, 40–61.</p><p class=\"entry-text\">② Participação em casamento dentro de graus proibidos de parentesco, fornicação (v. Lev. 18:16–18; cf. Acts 15:20–29, v. Bruce, com. Ac; 21:25) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a>; 19:9 (com alguma aprovação RSmith, Matthew [Augsburg] ’89,100; RGundry, Matthew ’82, 91: “não há necessidade de adotar definições obscuras de <span class=\"greek\">πορνείας</span>, como casamento dentro dos graus proibidos. … A palavra específica para adultério não aparece na cláusula de exceção simplesmente porque em Deuteronômio ocorre uma expressão geral” [24:1], mas v. BWitherington, NTS 31, ’85, 571–76: ‘exceto em caso de incesto’. Sobre estas passagens, v. 1.).</p><p class=\"entry-text\">③ Imoralidade de natureza transcendente, fornicação, em linguagem figurada, acerca do culto politeísta na cidade mística de Babilônia, que aparece em Rv como prostituta com clientela internacional. Desde o tempo de Oseias, a relação entre Deus e seu povo era considerada um vínculo matrimonial. Este emprego era mais facilmente compreensível porque alguns cultos semíticos e greco-romanos estavam por vezes ligados à devassidão sexual (cf. Hos 6:10; Jer 3:2, 9; 4 Km 9:22; pelo lado positivo, acerca da preocupação de alguns cultos com a decência, v. p. ex. SIG 820 [83/84 d.C.], em que uma autoridade efésia assegura a Roma que a festa anual da fertilidade no outono é celebrada ‘com muita castidade e devida observância dos costumes estabelecidos’. Este nível de conduta provavelmente se compara favoravelmente com atividades associadas à celebração de um carnaval moderno.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:2</a>. <span class=\"greek\">μετανοῆσαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">αὐτῆς</span> arrepender-se de sua imoralidade 2:21; cf. 9:21. <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶνος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. o vinho de sua imoralidade ardente 14:8; 18:3 (sobre estas passagens, v. <span class=\"greek\">θυμός</span> 1 e 2). <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶνος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. 17:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀκάθαρτα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. v. 4 (<span class=\"greek\">ἀκάθαρτος</span> 2).—V.l. em lugar de <span class=\"greek\">πονηρίας</span> Hv 1, 1, 8 (Leutzsch, Hermas 447 n. 53). V. artigo seguinte 2.—DELG s.v. <span class=\"greek\">πέρνημι</span>. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0294-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πορνεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πορνεύω</span> fut. <span class=\"greek\">πορνεύσω</span>; 1º aor. <span class=\"greek\">ἐπόρνευσα</span>; perf. 3ª pess. pl. <span class=\"greek\">πεπορνεύκασιν</span> Ezk 16:34 (Hdt. et al.; LXX, En; TestAbr A 10 p. 88, 8 [Stone p. 24]; Test12Patr; Ar. 15, 4; Just.; Tat. 34, 3), acerca de uma variedade de ‘relações sexuais não sancionadas’.</p><p class=\"entry-text\">① Praticar imoralidade sexual, ter relações sexuais ilícitas, fornicar, prostituir-se, na literatura grega frequentemente em referência à prostituição (v. L-S-J-M s.v.). Em sentido geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:8ab</a>. Distinguido de <span class=\"greek\">μοιχεύειν</span> ‘cometer adultério’ (Did., Job 133, 22ff [citação de Hos 4:14], 25ff); D 2:2; B 19:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:19</a> v.l. Considerado pecado contra o próprio corpo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:18</a>. Com <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">εἰδωλόθυτα</span> ‘comer carne oferecida aos ídolos’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:14</a>, 20.</p><p class=\"entry-text\">② Participação em culto politeísta, fornicação, em linguagem figurada (Phalaris, Ep. 121, 1), acerca do culto politeísta no sentido de ‘praticar o culto de imagens/idolatria’ (<span class=\"greek\">πορνεία</span> 3 e cf. Hos 9:1; Jer 3:6; Ezk 23:19; 1 Ch 5:25; Ps 72:27; En 8:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:2</a>; 18:3, 9.—DELG s.v. <span class=\"greek\">πέρνημι</span>. M-M. TW.</p></section></article>"};
